import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.CC9cRD7J.js";const o="/Staff-wiki/gui-examine.svg",f=JSON.parse('{"title":"Inspección de Inventario (/examine)","description":"","frontmatter":{},"headers":[],"relativePath":"moderacion/examinar-inventario.md","filePath":"moderacion/examinar-inventario.md","lastUpdated":1793575385000}'),r={name:"moderacion/examinar-inventario.md"};function s(l,e,d,c,g,u){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="inspeccion-de-inventario-examine" tabindex="-1">Inspección de Inventario (/examine) <a class="header-anchor" href="#inspeccion-de-inventario-examine" aria-label="Permalink to &quot;Inspección de Inventario (/examine)&quot;">​</a></h1><p><img src="'+o+'" alt="Interfaz de Inspección de Inventario"></p><p>El comando <code>/examine</code> abre una interfaz en tiempo real que replica exactamente lo que el jugador objetivo tiene en su poder, permitiendo auditar posibles objetos ilegales o duplicados.</p><hr><h2 id="🔍-uso-del-comando" tabindex="-1">🔍 Uso del Comando <a class="header-anchor" href="#🔍-uso-del-comando" aria-label="Permalink to &quot;🔍 Uso del Comando&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/examine</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jugado</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><em>(Permiso requerido: <code>staff.examine</code>)</em><em>También se puede activar usando el gadget del <strong>Cofre</strong> (Slot 8 de la hotbar de staff) haciendo clic derecho sobre el jugador.</em></p><hr><h2 id="🖥️-estructura-de-la-interfaz" tabindex="-1">🖥️ Estructura de la Interfaz <a class="header-anchor" href="#🖥️-estructura-de-la-interfaz" aria-label="Permalink to &quot;🖥️ Estructura de la Interfaz&quot;">​</a></h2><p>La pantalla de examen se divide en dos secciones principales:</p><h3 id="_1-inventario-del-jugador-slots-0-al-44" tabindex="-1">1. Inventario del Jugador (Slots 0 al 44) <a class="header-anchor" href="#_1-inventario-del-jugador-slots-0-al-44" aria-label="Permalink to &quot;1. Inventario del Jugador (Slots 0 al 44)&quot;">​</a></h3><ul><li><strong>Objetos del inventario y barra rápida:</strong> Muestra los ítems con sus encantamientos, lore y cantidades exactas.</li><li><strong>Armadura:</strong> Casco, pechera, pantalones y botas en tiempo real.</li><li><strong>Mano Secundaria (Offhand):</strong> En versiones 1.9+ y Paper 26.x, muestra el objeto equipado en la mano izquierda.</li></ul><h3 id="_2-barra-de-informacion-y-acciones-tacticas-ultima-fila" tabindex="-1">2. Barra de Información y Acciones Tácticas (Última fila) <a class="header-anchor" href="#_2-barra-de-informacion-y-acciones-tacticas-ultima-fila" aria-label="Permalink to &quot;2. Barra de Información y Acciones Tácticas (Última fila)&quot;">​</a></h3><p>La fila inferior ofrece accesos directos de diagnóstico y sanción:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Icono</th><th style="text-align:left;">Elemento</th><th style="text-align:left;">Información / Acción</th></tr></thead><tbody><tr><td style="text-align:center;">🍎</td><td style="text-align:left;"><strong>Comida y Salud</strong></td><td style="text-align:left;">Muestra los puntos de vida actuales y nivel de saturación.</td></tr><tr><td style="text-align:center;">🌐</td><td style="text-align:left;"><strong>Dirección IP</strong></td><td style="text-align:left;">Muestra la IP pública de conexión (oculta si el staff no tiene <code>staff.staffplus.hideip</code>).</td></tr><tr><td style="text-align:center;">📶</td><td style="text-align:left;"><strong>Ping y Latencia</strong></td><td style="text-align:left;">Muestra el tiempo de respuesta en milisegundos con el servidor.</td></tr><tr><td style="text-align:center;">🎮</td><td style="text-align:left;"><strong>Modo de Juego</strong></td><td style="text-align:left;">Indica si el jugador está en Supervivencia, Aventura, Creativo o Espectador.</td></tr><tr><td style="text-align:center;">⚠️</td><td style="text-align:left;"><strong>Infracciones</strong></td><td style="text-align:left;">Recuento de advertencias acumuladas por el usuario.</td></tr><tr><td style="text-align:center;">📍</td><td style="text-align:left;"><strong>Ubicación</strong></td><td style="text-align:left;">Coordenadas exactas (X, Y, Z, Mundo). Al hacer clic, te teletransporta a su posición.</td></tr><tr><td style="text-align:center;">📝</td><td style="text-align:left;"><strong>Notas</strong></td><td style="text-align:left;">Abre el panel de notas secretas asociadas al jugador.</td></tr><tr><td style="text-align:center;">❄️</td><td style="text-align:left;"><strong>Congelar</strong></td><td style="text-align:left;">Botón para congelar al jugador al instante sin salir de la interfaz.</td></tr><tr><td style="text-align:center;">🔨</td><td style="text-align:left;"><strong>Sancionar (Ban)</strong></td><td style="text-align:left;">Abre directamente el panel de <code>/bangui</code> con los datos del usuario cargados.</td></tr></tbody></table><hr><h2 id="✍️-modificacion-de-inventarios" tabindex="-1">✍️ Modificación de Inventarios <a class="header-anchor" href="#✍️-modificacion-de-inventarios" aria-label="Permalink to &quot;✍️ Modificación de Inventarios&quot;">​</a></h2><p>Si el moderador cuenta con el permiso <code>staff.examine.modify</code> (o es Operador):</p><ul><li>Puede retirar objetos sospechosos directamente arrastrándolos fuera de la interfaz para confiscarlos.</li><li>Si no dispone de este permiso, la interfaz es de <strong>solo lectura</strong>, impidiendo alteraciones accidentales.</li></ul>',19)])])}const m=t(r,[["render",s]]);export{f as __pageData,m as default};
